method.description:
Create a [PLATEAUInstancedCityModel] hierarchy from pre-extracted mesh data. The returned node contains metadata about the import including GeoReference data, LOD range, and mesh granularity.
[codeblock]
var city_model = PLATEAUCityModel.new()
city_model.load("path/to/file.gml")
var meshes = city_model.extract_meshes(options)

var importer = PLATEAUImporter.new()
var root = importer.import_to_scene(meshes, "MyCity", geo_ref, options, "path/to/file.gml")
add_child(root)

# Access metadata from PLATEAUInstancedCityModel
print("Zone ID: ", root.zone_id)
print("Latitude: ", root.get_latitude())
[/codeblock]
